export interface Maskapai {
  id: string;
  name: string;
  hargaJual: number;
  hargaBeli: number;
  margin: number;
  persen: number;
  programDays: number;
  tanggalKeberangkatan: string;
  tanggalKepulangan: string;
  originCityName: string;
  destinationCityName: string;
  namaVendor: string;
  totalSeats: number;
  availableSeats: number;
  ruteLabel?: string;
  hargaSetoran?: number;
  updatedAt?: string;
  tipePenerbangan?: "DIRECT" | "TRANSIT";
  flightItinerary?: string;
}

export const cleanMaskapaiDisplayName = (name?: string, vendorName?: string): string => {
  if (!name) return "";
  let clean = name;
  if (vendorName) {
    const escapedVendor = vendorName.replace(/[-/\\^$*+?.()|[\]{}]/g, "\\$&");
    clean = clean.replace(new RegExp(`\\s*\\(${escapedVendor}\\)`, "gi"), "");
  }
  clean = clean.replace(/\s*\((?:DAHLIA|IBU DAHLIA|NQH WISATA|NQH|PT BURGUNDY|Madani Tour|PT Cemerlang|PT AZZA BAROKAH MADINAH|PT AZZAHRA HARAMAIN WISATA|PT\. Darmawisata Indonesia|HAINANTIKET\.COM|PT ARRAYYAN AL MUBARAK|FATAYA|FRESHNEL|SAUDI AIRLINES|KANG RAFI)\)/gi, "");
  return clean.trim();
};

